#include "Aevrynd/Mesh3D.h"
#include "Aevrynd/Renderer.h"
#include "Aevrynd/TemporalMotion3D.h"
#include <cmath>
#include <dxgiformat.h>
#include <filesystem>
#include <iostream>
#include <limits>
using namespace Aevrynd;

static bool Near(float left,float right,float tolerance=.0001f){return std::abs(left-right)<=tolerance;}
static float MaximumMagnitude(const VelocityCapture3D& capture){float result{};for(const Vec2 velocity:capture.pixels)result=(std::max)(result,std::abs(velocity.x)+std::abs(velocity.y));return result;}
static bool SequenceOutputCleared(const RendererStats& stats){return!stats.temporalSequenceFingerprint&&!stats.temporalSequenceOutputIdentity&&!stats.temporalSequenceFence&&!stats.temporalSequenceOutputFormat&&!stats.temporalSequenceReused;}
static bool SequenceOutputPresent(const RendererStats& stats){return stats.temporalSequenceFingerprint&&stats.temporalSequenceOutputIdentity&&stats.temporalSequenceFence&&stats.temporalSequenceOutputFormat==uint32_t(DXGI_FORMAT_R11G11B10_FLOAT)&&!stats.temporalSequenceReused;}
static bool ValidationReceiptMatches(const RendererStats& stats,const char*& mode){wchar_t expected[8]{};const DWORD length=GetEnvironmentVariableW(L"AEVRYND_EXPECT_GPU_VALIDATION_MODE",expected,DWORD(std::size(expected)));if(length==6&&lstrcmpW(expected,L"normal")==0){mode="normal";return !stats.gpuValidationRequested&&!stats.gpuValidationAvailable&&!stats.gpuValidationExecuted&&!stats.debugLayerEnabled&&!stats.gpuValidationPassed&&!stats.debugErrorCount&&!stats.debugWarningCount;}if(length==3&&lstrcmpW(expected,L"gbv")==0){mode="gbv";return stats.gpuValidationRequested&&stats.gpuValidationAvailable&&stats.gpuValidationExecuted&&stats.debugLayerEnabled&&stats.gpuValidationPassed&&!stats.debugErrorCount&&!stats.debugWarningCount;}mode="missing-or-invalid";return false;}

int main(){
    HWND window=CreateWindowExW(0,L"STATIC",L"TemporalAntiAliasingProbe",WS_OVERLAPPED,0,0,128,128,nullptr,nullptr,GetModuleHandleW(nullptr),nullptr);
    if(!window)return 1;
    try{
        D3D12Renderer renderer;renderer.Initialize(window,128,128,128,128,false);renderer.SetQualitySettings({false,false,false,true});
        DrawList twoDimensional;renderer.Render(twoDimensional,{0,0,0,1});const RendererStats twoDimensionalStats=renderer.GetStats();
        if(twoDimensionalStats.temporalJitterEnabled||twoDimensionalStats.temporalHistoryUsed||twoDimensionalStats.temporalColorHistoryValid||twoDimensionalStats.temporalDepthHistoryValid||twoDimensionalStats.temporalHistoryResidentBytes||twoDimensionalStats.temporalDepthHistoryResidentBytes||twoDimensionalStats.velocityResidentBytes){std::cerr<<"Temporal 2D isolation failed\n";return 2;}
        const Mesh3D box=Mesh3D::CreateUnitBox();const MeshHandle3D mesh=renderer.CreateMesh(box.vertices,box.indices);
        auto make=[&](const Matrix4& transform,bool cameraCut){DrawList draw;draw.SetViewProjection(Matrix4::Identity());draw.SetBackfaceCulling(false);draw.SetCameraCut3D(cameraCut);draw.MeshInstance(mesh,transform,{1,.6f,.2f,1},{},MeshRenderLayer3D::Opaque,{},.25f,false,MaterialClass3D::Surface,std::numeric_limits<float>::quiet_NaN(),false,1,0,false,DirectionalShadowAllCascades3D,ShadowCascadeSelection3D::Automatic,Matrix4::Identity(),false,1,MaterialAlphaMode3D::Opaque,.5f,false,{{0x5441414c49464501ull,1},1});return draw;};
        const std::filesystem::path sequenceCapture=std::filesystem::temp_directory_path()/"aevrynd-temporal-lifecycle.png";
        auto runSequence=[&](DrawList draw,uint64_t serial){const auto token=renderer.BeginReadbackCaptureSequence3D({1,ReadbackCaptureSequenceJitterPolicy3D::FixedSample,0});if(!token)return false;const ObjectIdCaptureRequestMetadata3D metadata{serial,serial+1,serial+2,ReadbackEmptyReason3D::None,{*token,0},serial+3};std::error_code error;std::filesystem::remove(sequenceCapture,error);if(!renderer.CaptureNextFrame(sequenceCapture)||!renderer.RequestObjectIdReadback3D(metadata)||!renderer.RequestDepthReadback3D(metadata)){renderer.CancelReadbackCaptureSequence3D(*token);return false;}renderer.Render(draw,{0,0,0,1});const auto object=renderer.TakeObjectIdReadback3D();const auto depth=renderer.TakeDepthReadback3D();const auto sequence=renderer.EndReadbackCaptureSequence3D(*token);renderer.WaitIdle();std::filesystem::remove(sequenceCapture,error);return object&&object->Complete()&&depth&&depth->Complete()&&bool(sequence);};
        const TemporalJitterSample3D jitter0=CalculateTemporalJitterSample3D(0),jitter1=CalculateTemporalJitterSample3D(1);
        renderer.RequestVelocityReadback3D();renderer.Render(make(Matrix4::Identity(),true),{0,0,0,1});const auto cutVelocity=renderer.TakeVelocityReadback3D();RendererStats first=renderer.GetStats();
        if(!mesh||!cutVelocity||MaximumMagnitude(*cutVelocity)>.01f||!first.temporalAntiAliasingEnabled||!first.temporalJitterEnabled||first.temporalHistoryUsed||!first.temporalColorHistoryValid||!first.temporalDepthHistoryValid||!first.temporalHistoryValid||first.temporalJitterSequenceIndex!=0||!Near(first.currentTemporalJitterPixels.x,jitter0.pixelOffset.x)||!Near(first.currentTemporalJitterPixels.y,jitter0.pixelOffset.y)||first.temporalJitteredFrames!=1||first.temporalResolvePasses!=1||first.temporalDepthHistoryCopies!=1||first.temporalHistoryResidentBytes!=128ull*128*8||first.temporalDepthHistoryResidentBytes!=128ull*128*8||first.temporalHistoryAllocations!=1||first.temporalDepthHistoryAllocations!=1||first.temporalHistoryResourceFormat!=uint32_t(DXGI_FORMAT_R11G11B10_FLOAT)||first.temporalSequenceOutputFormat!=uint32_t(DXGI_FORMAT_R11G11B10_FLOAT)||first.temporalHistoryResourceFormat!=first.temporalSequenceOutputFormat||first.velocityResidentBytes!=128ull*128*4||first.velocityAllocations!=1||first.velocityPasses!=1){std::cerr<<"Temporal first frame failed\n";return 3;}
        renderer.RequestVelocityReadback3D();renderer.Render(make(Matrix4::Identity(),false),{0,0,0,1});const auto stationaryVelocity=renderer.TakeVelocityReadback3D();RendererStats accumulated=renderer.GetStats();
        if(!stationaryVelocity||MaximumMagnitude(*stationaryVelocity)>.01f||!accumulated.temporalAntiAliasingEnabled||!accumulated.temporalJitterEnabled||!accumulated.temporalHistoryUsed||!accumulated.temporalDepthHistoryValid||accumulated.temporalJitterSequenceIndex!=1||!Near(accumulated.currentTemporalJitterPixels.x,jitter1.pixelOffset.x)||!Near(accumulated.currentTemporalJitterPixels.y,jitter1.pixelOffset.y)||!Near(accumulated.previousTemporalJitterPixels.x,jitter0.pixelOffset.x)||!Near(accumulated.previousTemporalJitterPixels.y,jitter0.pixelOffset.y)||accumulated.temporalJitteredFrames!=2||accumulated.temporalResolvePasses!=2||accumulated.temporalDepthHistoryCopies!=2||accumulated.temporalHistoryAllocations!=1||accumulated.temporalDepthHistoryAllocations!=1||accumulated.velocityPasses!=2){std::cerr<<"Temporal accumulation failed\n";return 4;}
        renderer.Render(make(Matrix4::Identity(),true),{0,0,0,1});const RendererStats cameraCut=renderer.GetStats();
        if(cameraCut.temporalHistoryUsed||cameraCut.temporalJitterSequenceIndex!=0||!Near(cameraCut.currentTemporalJitterPixels.x,jitter0.pixelOffset.x)||!Near(cameraCut.currentTemporalJitterPixels.y,jitter0.pixelOffset.y)||cameraCut.temporalJitteredFrames!=3||cameraCut.temporalJitterResets<1||cameraCut.temporalResolvePasses!=3){std::cerr<<"Temporal camera cut reset failed\n";return 5;}
        if(!runSequence(make(Matrix4::Identity(),false),0x1000)){std::cerr<<"Temporal sequence setup failed\n";return 6;}const RendererStats beforeResize=renderer.GetStats();
        if(!SequenceOutputPresent(beforeResize)||beforeResize.temporalResolvePasses!=4||beforeResize.temporalDepthHistoryCopies!=4){std::cerr<<"Temporal sequence diagnostics setup failed\n";return 6;}
        renderer.Resize(96,64);const RendererStats resizeReleased=renderer.GetStats();
        if(!SequenceOutputCleared(resizeReleased)||resizeReleased.temporalHistoryResourceFormat!=uint32_t(DXGI_FORMAT_R11G11B10_FLOAT)||resizeReleased.temporalHistoryResidentBytes!=96ull*64*8||resizeReleased.temporalDepthHistoryResidentBytes!=96ull*64*8||resizeReleased.temporalColorHistoryValid||resizeReleased.temporalDepthHistoryValid||resizeReleased.temporalHistoryValid){std::cerr<<"Temporal resize release diagnostics failed\n";return 6;}
        renderer.Render(make(Matrix4::Identity(),true),{0,0,0,1});RendererStats resized=renderer.GetStats();
        if(!resized.temporalAntiAliasingEnabled||resized.temporalHistoryUsed||!resized.temporalDepthHistoryValid||resized.temporalJitterSequenceIndex!=0||resized.temporalJitteredFrames!=5||resized.temporalJitterResets<2||resized.temporalResolvePasses!=5||resized.temporalDepthHistoryCopies!=5||resized.temporalHistoryResidentBytes!=96ull*64*8||resized.temporalDepthHistoryResidentBytes!=96ull*64*8||resized.temporalHistoryAllocations!=2||resized.temporalDepthHistoryAllocations!=2||resized.temporalHistoryReleases!=1||resized.temporalDepthHistoryReleases!=1||resized.velocityResidentBytes!=96ull*64*4||resized.velocityAllocations!=2||resized.velocityReleases!=1){std::cerr<<"Temporal resize lifecycle failed\n";return 6;}
        if(!runSequence(make(Matrix4::Identity(),false),0x2000)||!SequenceOutputPresent(renderer.GetStats())){std::cerr<<"Temporal resize diagnostics restore failed\n";return 6;}
        renderer.SetQualitySettings({false,false,false,false});RendererStats disabled=renderer.GetStats();
        if(!SequenceOutputCleared(disabled)||disabled.temporalHistoryResourceFormat||disabled.temporalHistoryResidentBytes||disabled.temporalDepthHistoryResidentBytes||disabled.velocityResidentBytes||disabled.temporalColorHistoryValid||disabled.temporalDepthHistoryValid||disabled.temporalHistoryValid||disabled.temporalHistoryReleases!=2||disabled.temporalDepthHistoryReleases!=2||disabled.velocityReleases!=2||disabled.qualityResourceReleases<2){std::cerr<<"Temporal quality release failed\n";return 7;}
        renderer.SetQualitySettings({false,false,false,true});renderer.Render(make(Matrix4::Identity(),true),{0,0,0,1});if(!runSequence(make(Matrix4::Identity(),false),0x3000)||!SequenceOutputPresent(renderer.GetStats())){std::cerr<<"Temporal quality diagnostics restore failed\n";return 8;}renderer.TrimTransientMemory();RendererStats trimmed=renderer.GetStats();
        if(!SequenceOutputCleared(trimmed)||trimmed.temporalHistoryResourceFormat||trimmed.temporalHistoryResidentBytes||trimmed.temporalDepthHistoryResidentBytes||trimmed.velocityResidentBytes||trimmed.temporalHistoryReleases!=3||trimmed.temporalDepthHistoryReleases!=3||trimmed.velocityReleases!=3){std::cerr<<"Temporal trim lifecycle failed\n";return 8;}
        renderer.DestroyMesh(mesh);renderer.WaitIdle();const RendererStats receipt=renderer.GetStats();const char* mode{};if(!ValidationReceiptMatches(receipt,mode)){std::cerr<<"Temporal validation receipt mode failed: "<<mode<<" requested="<<receipt.gpuValidationRequested<<" available="<<receipt.gpuValidationAvailable<<" executed="<<receipt.gpuValidationExecuted<<" debug="<<receipt.debugLayerEnabled<<" passed="<<receipt.gpuValidationPassed<<" errors="<<receipt.debugErrorCount<<" warnings="<<receipt.debugWarningCount<<'\n';DestroyWindow(window);return 10;}DestroyWindow(window);std::cout<<"resolves="<<trimmed.temporalResolvePasses<<" allocations="<<trimmed.temporalHistoryAllocations<<" releases="<<trimmed.temporalHistoryReleases<<" historyFormat="<<first.temporalHistoryResourceFormat<<" identityFormat="<<first.temporalSequenceOutputFormat<<" validationMode="<<mode<<'\n';return 0;
    }catch(const std::exception& error){std::cerr<<error.what()<<'\n';DestroyWindow(window);return 9;}
}
